    TwistSquash::SquashKeyA(CAPELLA_KEY_B_D_IceLaneA, CAPELLA_KEY_B_D_IceLaneB, CAPELLA_KEY_B_D_IceLaneC, CAPELLA_KEY_B_D_IceLaneD, &(pWorkSpace->mKeyBoxB[3U][0]));

