        const std::size_t aSourceIndexB = 1U * (S_HALF >> 1U) + 3U * W_KEY + ((aIndex + 601U) & W_KEY1);
        const std::size_t aSourceIndexC = 1U * (S_HALF >> 1U) + 2U * W_KEY + ((aIndex + 556U) & W_KEY1);
        const std::size_t aSourceIndexD = 1U * (S_HALF >> 1U) + 2U * W_KEY + ((aIndex + 511U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * W_KEY + aIndex;

        std::uint32_t aFoldValue = 0U;
